#!/usr/bin/env bash
# bitnami/elasticsearch 22.1.6 - base variant: ha
# Path: pull the package, render this base variant locally, read the objects,
# then apply them with kubectl. No ConfigHub account is needed.
# Generated by scripts/generate-public-site.mjs from the committed package
# data for this base variant. Chart page: https://confighub.github.io/helm-expt/site/charts/bitnami-elasticsearch-22-1-6.html
set -euo pipefail

say() { printf '\n>> %s\n' "$*"; }

if ! command -v cub >/dev/null 2>&1; then
  printf 'cub is not installed. Install the cub CLI with:\n  curl -fsSL https://hub.confighub.com/cub/install.sh | bash\nthen add ~/.confighub/bin to your PATH and re-run this script.\n' >&2
  exit 1
fi

# Public cub releases include the installer command. This guard catches
# an older or incomplete CLI before this script does any work.
if ! cub installer --help >/dev/null 2>&1; then
  printf 'This cub build does not include cub installer. Install or upgrade the cub CLI with:\n  curl -fsSL https://hub.confighub.com/cub/install.sh | bash\nthen add ~/.confighub/bin to your PATH and re-run this script.\n' >&2
  exit 1
fi

if ! command -v kubectl >/dev/null 2>&1; then
  printf 'kubectl is required for the apply step.\n' >&2
  exit 1
fi

say "Pull the package and render the ha base variant into ./bitnami-elasticsearch-22-1-6-ha"
cub installer setup --pull oci://europe-west1-docker.pkg.dev/nth-fort-499605-q5/helm-expt/bitnami-elasticsearch:22.1.6 --base ha --work-dir ./bitnami-elasticsearch-22-1-6-ha --non-interactive --namespace default

say "Read what was rendered; nothing has touched the cluster yet"
ls ./bitnami-elasticsearch-22-1-6-ha/out/manifests

say "Ensure the default namespace exists"
kubectl create namespace default --dry-run=client -o yaml | kubectl apply -f -

if [ -d ./bitnami-elasticsearch-22-1-6-ha/out/secrets ]; then
  say "Apply rendered Secrets first"
  kubectl apply -f ./bitnami-elasticsearch-22-1-6-ha/out/secrets
fi

say "Apply the rendered objects"
kubectl apply -f ./bitnami-elasticsearch-22-1-6-ha/out/manifests

say "Done. The cluster received exactly the files in ./bitnami-elasticsearch-22-1-6-ha/out."
